import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as e,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"协议观察清单","description":"尚未达到 canonical 章门槛的 Agent 协议观察卡合集——发现/目录、支付/商务、Web/交互三组；每卡记录 owner、canonical URL、状态与缺口，并声明纳入门槛与 discovery≠信任≠授权。","frontmatter":{"title":"协议观察清单","description":"尚未达到 canonical 章门槛的 Agent 协议观察卡合集——发现/目录、支付/商务、Web/交互三组；每卡记录 owner、canonical URL、状态与缺口，并声明纳入门槛与 discovery≠信任≠授权。","domain":"tech","tags":["tech","action","protocols","watchlist","landscape"],"navOrder":76,"topicId":"protocol-watchlist","layer":"7","status":"watchlist","nodeType":"resource","owner":"learn-ai","externalOwners":[],"prerequisites":["protocol-map"],"next":[],"specVersion":"多协议观察卡（各卡自带状态与 retrievedAt，统检 2026-09-01）","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/07-interoperability/watchlist.md","filePath":"zh/tech/07-interoperability/watchlist.md","lastUpdated":1791123720000}'),n={name:"zh/tech/07-interoperability/watchlist.md"};function i(l,t,s,c,g,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<blockquote><p><strong>所在组</strong>：互操作 ｜ <strong>上一组出口</strong>：能构建可追溯的检索链和更新路径 ｜ <strong>本组出口</strong>：遇到清单内协议能立刻说出它解决什么、归谁、缺什么门槛 <strong>前置</strong>：<a href="./">协议地图</a> ｜ <strong>下一步</strong>：达到门槛的协议将升格为独立 canonical 章</p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：Agent 协议生态的产出速度远超任何教程的改版速度。本页是<strong>观察卡合集</strong>，不是教程：每张卡回答「全称、归谁、canonical URL 在哪、状态如何、边界是什么、为什么还没进 canonical」。清单按三组组织——发现与目录、支付与商务、交互与 Web。</p><p><strong>结构声明（精简五段式）</strong>：本页 status 为 watchlist，省略完整「使用 / 原理 / 开发」段，以观察卡代替——理由：观察对象普遍缺少可零密钥复验的公开规范成熟度与可运行 fixture；保留资料库段。各卡字段以 2026-09-01 检索为准。</p><h3 id="纳入门槛-何时升格为-canonical-章" tabindex="-1">纳入门槛（何时升格为 canonical 章） <a class="header-anchor" href="#纳入门槛-何时升格为-canonical-章" aria-label="Permalink to &quot;纳入门槛（何时升格为 canonical 章）&quot;">​</a></h3><p>同时满足以下五条，才从观察区升格：</p><ol><li><strong>公开且版本化的规范</strong>（版本化 URL 或正式标准轨道），字段级可引。</li><li><strong>独立问题边界</strong>：与现有 canonical 章（MCP / A2A / ACP / AG-UI / A2UI-MCP Apps）不重叠，能说清「它解决的问题其他协议不解决」。</li><li><strong>可运行 fixture</strong>：零 API key、确定性、clean checkout 可复现。</li><li><strong>成文的安全模型</strong>：认证/授权/注入防护有规范级描述，而非博客级口号。</li><li><strong>可核验的维护路径</strong>：治理主体、变更流程、弃用政策可查。</li></ol><h3 id="三条铁律" tabindex="-1">三条铁律 <a class="header-anchor" href="#三条铁律" aria-label="Permalink to &quot;三条铁律&quot;">​</a></h3><ul><li><strong>discovery ≠ 信任 ≠ 授权</strong>：发现机制（ARD、Registry、目录、ANS）只解决「找到」；身份可信要靠签名/身份层（A2A Card 的 JWS、DID、ANS 的 PKI 方案）；能否行动要靠授权层（OAuth、权限模型）。任何一层都不能替代另一层。</li><li><strong>同名≠同物</strong>：ACP 至少四义（<a href="./acp-agent-client.html">Agent Client Protocol</a> / IBM 历史 ACP / AGNTCY Agent Connect Protocol / OpenClaw 私有）；ADL、OAP 也各有多个同名竞争方案（见卡）。引用永远带全称 + canonical URL。</li><li><strong>快照会过期</strong>：IETF Internet-Draft 六个月过期；Candidate/Proposal 状态随时可变。本页所有断言带 retrievedAt，引用前自查最新版。</li></ul><h2 id="_2-观察卡-发现与目录" tabindex="-1">2. 观察卡：发现与目录 <a class="header-anchor" href="#_2-观察卡-发现与目录" aria-label="Permalink to &quot;2. 观察卡：发现与目录&quot;">​</a></h2><h3 id="ard-—-agentic-resource-discovery" tabindex="-1">ARD — Agentic Resource Discovery <a class="header-anchor" href="#ard-—-agentic-resource-discovery" aria-label="Permalink to &quot;ARD — Agentic Resource Discovery&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Agentic Resource Discovery Specification；作者 Junjie Bu（Google）、R.V. Guha（Microsoft）、Shaun Smith（Hugging Face）。</li><li><strong>canonical</strong>：<a href="https://agenticresourcediscovery.org/spec/" target="_blank" rel="noreferrer">https://agenticresourcediscovery.org/spec/</a></li><li><strong>状态</strong>：v0.91，Status: Proposal，规范自署日期 2026-08-26（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：跨联邦网络描述/发现/检索「agentic resources」（MCP 工具、A2A agent、skills 等_callable 资源）；条目为 JSON-LD 节点；含 <code>/explore</code>、<code>GET /agents</code> 可选方法与 URN 命名附录。</li><li><strong>为何在观察区</strong>：Proposal 状态、v0.x 版本线、安全护栏（条目签名/信任）未成文完整；无独立 fixture。</li></ul><h3 id="mcp-registry" tabindex="-1">MCP Registry <a class="header-anchor" href="#mcp-registry" aria-label="Permalink to &quot;MCP Registry&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Model Context Protocol Registry；modelcontextprotocol 组织（GitHub）。</li><li><strong>canonical</strong>：<a href="https://github.com/modelcontextprotocol/registry" target="_blank" rel="noreferrer">https://github.com/modelcontextprotocol/registry</a></li><li><strong>状态</strong>：活跃仓库，「community driven registry service for MCP servers」（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：MCP server 的社区注册表——解决「上哪找可信 server」的分发问题，不定义 server 本身协议。</li><li><strong>为何在观察区</strong>：注册表是服务/基础设施而非协议契约；升格路径是并入 <a href="./mcp.html">MCP</a> 章的发现小节，而非独立章。</li></ul><h3 id="agntcy-oasf-dir-slim-身份与可观测" tabindex="-1">AGNTCY（OASF / DIR / SLIM + 身份与可观测） <a class="header-anchor" href="#agntcy-oasf-dir-slim-身份与可观测" aria-label="Permalink to &quot;AGNTCY（OASF / DIR / SLIM + 身份与可观测）&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：AGNTCY（&quot;Internet of Agents&quot; 开源栈）；Linux Foundation 旗下 LF Projects，Outshift（Cisco 孵化）发起。</li><li><strong>canonical</strong>：<a href="https://www.agntcy.org/" target="_blank" rel="noreferrer">https://www.agntcy.org/</a></li><li><strong>状态</strong>：活跃，多语言 SDK（Go/Python/.NET/Java/Kotlin 等），Apache-2.0（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：<strong>DIR</strong>（Agent Directory Service）——跨框架/跨协议/跨注册表的联邦 agent 发现；<strong>SLIM</strong>——agent 间安全网络层消息传输；<strong>OASF</strong>——agent/技能描述的版本化 schema 框架（含技能/领域分类法）；另有 Identity（W3C 可验证凭据徽章）与 Observability 组件。缩写展开以官方文档为准（首页未逐一展开，未核验）。</li><li><strong>为何在观察区</strong>：栈内组件与既有 canonical 重叠度高（描述 schema vs Agent Card；发现 vs ARD/Registry；消息 vs A2A 绑定）；独立问题边界待论证。</li></ul><h3 id="dns-aid-ans-家族-ietf-草案群" tabindex="-1">DNS-AID / ANS 家族（IETF 草案群） <a class="header-anchor" href="#dns-aid-ans-家族-ietf-草案群" aria-label="Permalink to &quot;DNS-AID / ANS 家族（IETF 草案群）&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：多个个人提交的 IETF Internet-Draft，互不隶属。</li><li><strong>canonical</strong>（均在 <a href="https://datatracker.ietf.org/%EF%BC%8CretrievedAt" target="_blank" rel="noreferrer">https://datatracker.ietf.org/，retrievedAt</a> 2026-09-01，全部 &quot;work in progress&quot;）： <ul><li><strong>AID</strong>：<code>draft-nemethi-aid-agent-identity-discovery</code> —— <code>_agent.&lt;domain&gt;</code> TXT 记录做协议无关引导（v1.2）。</li><li><strong>ANS</strong>：<code>draft-narajala-ans</code>（DNS 风格目录 + PKI）与 <code>draft-narajala-courtney-ansv2</code>（域名锚定 + ACME + 透明日志，铜/银/金三级）。</li><li><strong>DN-ANR</strong>：<code>draft-cui-dns-native-agent-naming-resolution</code> —— FQDN 为 Agent ID，SVCB/HTTPS RR + DNSSEC 解析。</li><li><strong>AGTP ANS</strong>：<code>draft-hood-agtp-discovery</code> —— DISCOVER 方法 + 治理型名字服务。</li></ul></li><li><strong>边界</strong>：共同命题「Agent 的 DNS」——命名、解析、端点验证；均显式声明不做语义发现或授权。</li><li><strong>为何在观察区</strong>：全部是六个月过期的个人草案，尚无一个进入 WG/RFC 轨道；多家竞争同一位置，等收敛。</li></ul><h3 id="adl-oap-agent-定义与打包-同名竞争区" tabindex="-1">ADL / OAP（Agent 定义与打包，同名竞争区） <a class="header-anchor" href="#adl-oap-agent-定义与打包-同名竞争区" aria-label="Permalink to &quot;ADL / OAP（Agent 定义与打包，同名竞争区）&quot;">​</a></h3><ul><li><strong>ADL</strong>： <ul><li><strong>canonical</strong>：<a href="https://datatracker.ietf.org/doc/html/draft-nederveld-adl-02%EF%BC%88%E4%B8%AA%E4%BA%BA%E6%8F%90%E4%BA%A4%EF%BC%8CStandards" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/html/draft-nederveld-adl-02（个人提交，Standards</a> Track 意向；<code>application/adl+json</code>；&quot;passport&quot; 模型；声明可转换为 A2A Agent Card 与 MCP 配置）。retrievedAt 2026-09-01。</li><li>社区另有至少两个同名方案（inference-gateway 的 ADL、nextmoca 的 ADL，均自述 &quot;OpenAPI for AI Agents&quot;）——同名不同 schema。</li></ul></li><li><strong>OAP</strong>： <ul><li><strong>canonical A</strong>：<a href="http://openagentprotocol.eu/%EF%BC%88%E4%B8%83%E5%B9%B3%E9%9D%A2%EF%BC%9A%E8%BA%AB%E4%BB%BD/%E5%8F%91%E7%8E%B0/%E8%B0%83%E7%94%A8/%E5%95%86%E5%8A%A1/%E6%B2%BB%E7%90%86/%E9%97%AE%E8%B4%A3/%E5%8D%8F%E8%B0%83%EF%BC%9B%60/.well-known/oap-tool.json%60%EF%BC%9B37" target="_blank" rel="noreferrer">http://openagentprotocol.eu/（七平面：身份/发现/调用/商务/治理/问责/协调；`/.well-known/oap-tool.json`；37</a> 个 RFC 流程稿）。retrievedAt 2026-09-01。</li><li><strong>canonical B</strong>：<a href="https://github.com/open-agentic-protocol/%EF%BC%88%E7%99%BD%E7%9A%AE%E4%B9%A6" target="_blank" rel="noreferrer">https://github.com/open-agentic-protocol/（白皮书</a> v0.2；OAPverse 注册表构想）。</li></ul></li><li><strong>边界</strong>：Agent 的<strong>定义/清单格式</strong>（静态描述），不是通信协议。</li><li><strong>为何在观察区</strong>：同名多案、均为草案/白皮书；与 A2A Agent Card 的关系是「生成它」还是「取代它」未收敛；无独立运行面。</li></ul><h3 id="anp-—-agent-network-protocol" tabindex="-1">ANP — Agent Network Protocol <a class="header-anchor" href="#anp-—-agent-network-protocol" aria-label="Permalink to &quot;ANP — Agent Network Protocol&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Agent Network Protocol（智能体网络协议）；社区项目（agentnetworkprotocol.com），另有 IETF 侧 <code>draft-song-anp-*</code> 草案套件（AIP/AITP/ANS/ADP 四件，P2P 数据报 + agent:// URI + DHT/GossipSub）。</li><li><strong>canonical</strong>：<a href="https://www.anp-protocol.com/" target="_blank" rel="noreferrer">https://www.anp-protocol.com/</a> 与 <a href="https://datatracker.ietf.org/%EF%BC%88%E8%8D%89%E6%A1%88%E6%A3%80%E7%B4%A2%EF%BC%89" target="_blank" rel="noreferrer">https://datatracker.ietf.org/（草案检索）</a></li><li><strong>状态</strong>：社区站活跃（中英双语），IETF 套件为个人草案（均 retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：去中心化身份（W3C DID，<code>did:wba</code>）+ 元协议协商 + 应用协议的三层栈，面向「数十亿智能体互联网」。</li><li><strong>为何在观察区</strong>：与 A2A 的中心化 HTTP 模型是路线之争而非补充关系，生产采用未验证；两轨（社区站 vs IETF 草案）关系需持续观察。</li></ul><h3 id="ahp-—-agent-host-protocol" tabindex="-1">AHP — Agent Host Protocol <a class="header-anchor" href="#ahp-—-agent-host-protocol" aria-label="Permalink to &quot;AHP — Agent Host Protocol&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Agent Host Protocol；Microsoft（GitHub Pages 规范站）。</li><li><strong>canonical</strong>：<a href="https://microsoft.github.io/agent-host-protocol/specification/overview" target="_blank" rel="noreferrer">https://microsoft.github.io/agent-host-protocol/specification/overview</a></li><li><strong>状态</strong>：<strong>DRAFT</strong>（规范自标；破坏性变更预期）（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：JSON-RPC 2.0、传输无关、SemVer 版本协商、channel 化的消息/命令/通知/动作；<code>x-</code> 前缀保留给实现扩展。</li><li><strong>为何在观察区</strong>：DRAFT 且破坏性变更在即；「宿主-Agent」边界与 ACP 的编辑器-Agent 边界如何区分尚不清楚。</li></ul><h2 id="_3-观察卡-支付与商务" tabindex="-1">3. 观察卡：支付与商务 <a class="header-anchor" href="#_3-观察卡-支付与商务" aria-label="Permalink to &quot;3. 观察卡：支付与商务&quot;">​</a></h2><h3 id="ucp-—-universal-commerce-protocol" tabindex="-1">UCP — Universal Commerce Protocol <a class="header-anchor" href="#ucp-—-universal-commerce-protocol" aria-label="Permalink to &quot;UCP — Universal Commerce Protocol&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Universal Commerce Protocol；行业联盟（站点列 Google、Shopify、Microsoft、OpenAI、Stripe、Walmart、Booking 等数十家，retrievedAt 2026-09-01）。</li><li><strong>canonical</strong>：<a href="https://ucp.dev/" target="_blank" rel="noreferrer">https://ucp.dev/</a></li><li><strong>状态</strong>：规范站已上线，正扩展到住宿/餐饮（&quot;Detailed specifications coming soon&quot;）；版本号未在首页展示。</li><li><strong>边界</strong>：agentic commerce 的总装层——从发现到结账；REST/JSON-RPC 传输，内置 AP2（支付）、A2A、MCP 支持；OAuth 2.0 账号绑定。</li><li><strong>为何在观察区</strong>：规范主体尚未公开到字段级；上层编排与 UCP/AP2/既有电商 API 的边界待成文。</li></ul><h3 id="ap2-—-agent-payments-protocol" tabindex="-1">AP2 — Agent Payments Protocol <a class="header-anchor" href="#ap2-—-agent-payments-protocol" aria-label="Permalink to &quot;AP2 — Agent Payments Protocol&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Agent Payments Protocol（规范页亦作 Agentic Payment Protocol）；Google 系（规范站 ap2-protocol.org）。</li><li><strong>canonical</strong>：<a href="https://ap2-protocol.org/ap2/specification/" target="_blank" rel="noreferrer">https://ap2-protocol.org/ap2/specification/</a></li><li><strong>状态</strong>：v0.2（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：<strong>支付安全层</strong>而非商务协议——Checkout Mandate/Receipt + 关联的 Payment Mandate/Receipt，作为争议证据；五角色模型（Shopping Agent、Credential Provider、Merchant、Merchant Payment Processor 等）；显式声明与 UCP 兼容，商品目录等商务细节不在范围内。</li><li><strong>为何在观察区</strong>：v0.x；与 x402/MPP 的市场竞争未收敛；与 A2A 的 AUTH_REQUIRED 委托链如何衔接未成文。</li></ul><h3 id="x402" tabindex="-1">x402 <a class="header-anchor" href="#x402" aria-label="Permalink to &quot;x402&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：x402；x402 Foundation（Coinbase 起源）。</li><li><strong>canonical</strong>：<a href="https://x402.org/" target="_blank" rel="noreferrer">https://x402.org/</a></li><li><strong>状态</strong>：活跃（站点自报近 30 日 75.41M 笔交易——<strong>站点自述数，未经审计</strong>，retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：HTTP 402 原生支付——服务端一行中间件对未付费请求回 402，客户端付费重试；稳定币链上结算、零协议费、网络无关。</li><li><strong>为何在观察区</strong>：加密轨道依赖（稳定币-only）与主流企业财务流程差距大；采用数据无独立审计源。</li></ul><h3 id="agentic-commerce-protocol-openai-stripe-缩写亦为-acp" tabindex="-1">Agentic Commerce Protocol（OpenAI/Stripe，缩写亦为 ACP） <a class="header-anchor" href="#agentic-commerce-protocol-openai-stripe-缩写亦为-acp" aria-label="Permalink to &quot;Agentic Commerce Protocol（OpenAI/Stripe，缩写亦为 ACP）&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Agentic Commerce Protocol；OpenAI + Stripe 共同发起（2025-09-29 宣布，Apache 2.0）。</li><li><strong>canonical</strong>：<a href="https://developers.openai.com/commerce" target="_blank" rel="noreferrer">https://developers.openai.com/commerce</a> 与 <a href="https://github.com/agentic-commerce-protocol" target="_blank" rel="noreferrer">https://github.com/agentic-commerce-protocol</a></li><li><strong>状态</strong>：已驱动 ChatGPT Instant Checkout 上线；变更日志持续更新（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：三件套规范——Product Feed（结构化商品数据）、Agentic Checkout（对话内结账会话）、Delegated Payment（委托支付，Stripe Shared Payment Token 为首个实现）；商家保持 Merchant of Record。</li><li><strong>为何在观察区</strong>：边界是「ChatGPT 内购物」生态而非通用 agent 协作；<strong>缩写与 <a href="./acp-agent-client.html">Agent Client Protocol</a> 冲突</strong>，引用必须写全称。</li></ul><h3 id="mpp-—-machine-payments-protocol" tabindex="-1">MPP — Machine Payments Protocol <a class="header-anchor" href="#mpp-—-machine-payments-protocol" aria-label="Permalink to &quot;MPP — Machine Payments Protocol&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Machine Payments Protocol；Stripe + Tempo 共同作者（2026-03-18 发布）。</li><li><strong>canonical</strong>：<a href="https://mpp.dev/%EF%BC%88IETF" target="_blank" rel="noreferrer">https://mpp.dev/（IETF</a> 侧认证方案草案：paymentauth.org）</li><li><strong>状态</strong>：开放标准，发布时百余家服务接入（媒体报道，retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：HTTP 402 复活的另一支——<code>WWW-Authenticate: Payment</code> 挑战 / <code>Authorization: Payment</code> 凭据 / <code>Payment-Receipt</code> 回执；charge 与 session 两种 intent；多轨道（Tempo 稳定币、Stripe SPT 卡、Visa 扩展、Lightning）；与 x402 核心流可映射兼容。</li><li><strong>为何在观察区</strong>：与 x402 同题竞争（同用 402，头设计不同）；支付协议的采用取决于财务/合规栈，非技术单因。</li></ul><h3 id="opensharing" tabindex="-1">OpenSharing <a class="header-anchor" href="#opensharing" aria-label="Permalink to &quot;OpenSharing&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：OpenSharing；Linux Foundation 项目（Databricks 发起，Delta Sharing 的演进）。</li><li><strong>canonical</strong>：<a href="https://opensharing.io/%EF%BC%88%E6%B3%A8%E6%84%8F%EF%BC%9A**opensharing.org" target="_blank" rel="noreferrer">https://opensharing.io/（注意：**opensharing.org</a> 是无关站点**，勿混淆）</li><li><strong>状态</strong>：2026-06-10 宣布立项（新闻稿 + 社区报道，retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：AI 资产（agent skills、模型、非结构化数据）的零拷贝共享协议——凭证自动售货（STS/SAS/OAuth 短时令牌），接收方直连提供方存储，共享服务器不在数据路径上。</li><li><strong>为何在观察区</strong>：刚立项；与 MCP 的资源分发、与 Skills 的资产打包边界待规范成文。</li></ul><h2 id="_4-观察卡-交互与-web" tabindex="-1">4. 观察卡：交互与 Web <a class="header-anchor" href="#_4-观察卡-交互与-web" aria-label="Permalink to &quot;4. 观察卡：交互与 Web&quot;">​</a></h2><h3 id="webmcp" tabindex="-1">WebMCP <a class="header-anchor" href="#webmcp" aria-label="Permalink to &quot;WebMCP&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：WebMCP；W3C Web Machine Learning Community Group（Google/Microsoft 工程师贡献）。</li><li><strong>canonical</strong>：W3C WebML CG 草案（二手来源指向 webmachinelearning.github.io/webmcp；<strong>本轮直接核验失败</strong>——w3c.github.io/webmcp 为 404，retrievedAt 2026-09-01）。</li><li><strong>状态</strong>：<strong>Draft Community Group Report——不是 W3C 标准、不在标准轨道上</strong>；Chrome origin trial（2026-06 报道，Chrome 149）。</li><li><strong>边界</strong>：浏览器原生 API——页面通过 <code>document.modelContext.registerTool()</code>（早期 <code>navigator.modelContext</code>）向页内 agent 暴露带 JSON Schema 的工具；另有把 HTML 表单注解成工具的声明式路径（规范中该节尚标 TODO）。非目标：无头/完全自治浏览。</li><li><strong>为何在观察区</strong>：CG 草案 + origin trial 阶段；安全节未完成；跨浏览器支持为零时不可作为产品依赖。</li></ul><h3 id="nlip-—-natural-language-interaction-protocol" tabindex="-1">NLIP — Natural Language Interaction Protocol <a class="header-anchor" href="#nlip-—-natural-language-interaction-protocol" aria-label="Permalink to &quot;NLIP — Natural Language Interaction Protocol&quot;">​</a></h3><ul><li><strong>全称/owner</strong>：Natural Language Interaction Protocol；Ecma International TC56。</li><li><strong>canonical</strong>：<a href="https://ecma-international.org/publications-and-standards/standards/ecma-430/" target="_blank" rel="noreferrer">https://ecma-international.org/publications-and-standards/standards/ecma-430/</a></li><li><strong>状态</strong>：<strong>ECMA-430，已发布的 Ecma 标准</strong>（正式标准，非草案；发布日期未在检索页展示，未验证）（retrievedAt 2026-09-01）。</li><li><strong>边界</strong>：「AI Agent 之间、或人与 AI agent 之间」的应用层通信协议；动机与设计哲学明确排除在标准文本之外。</li><li><strong>为何在观察区</strong>：正式标准但生态采用度未知（无独立采用数据）；与 A2A/ACP 的问题边界重叠度高，独立性待证。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><h3 id="四级阅读路线" tabindex="-1">四级阅读路线 <a class="header-anchor" href="#四级阅读路线" aria-label="Permalink to &quot;四级阅读路线&quot;">​</a></h3><ul><li><strong>Beginner</strong>：本页三组卡片按需查（先看组再看卡）→ 回 <a href="./">协议地图</a> 复位。</li><li><strong>Builder</strong>：对某卡动心时，先做门槛自检（§1 五条）——尤其是「零密钥 fixture 你能写出吗」。</li><li><strong>Operator</strong>：把本页当选型禁区清单：任何清单内协议进生产前，先补身份与授权两层设计。</li><li><strong>Researcher</strong>：IETF datatracker 订阅相关草案邮件列表；跟踪 A2A/MCP/ACP 官方 changelog 观察收敛信号。</li></ul><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>本页各观察卡</td><td>L0/L2 混合</td><td>见各卡</td><td>快速定位协议归属与状态</td><td>各卡内断言（均带 retrievedAt）</td><td>点 canonical 自查最新态</td></tr><tr><td>IETF Datatracker</td><td>L0</td><td><a href="https://datatracker.ietf.org/" target="_blank" rel="noreferrer">https://datatracker.ietf.org/</a></td><td>草案状态与过期检查</td><td>DNS-AID/ANS、ADL、ANP 套件均为 &quot;work in progress&quot;</td><td>订阅邮件列表</td></tr><tr><td>a2a-protocol.org / agentclientprotocol.com</td><td>L0</td><td>见对应 canonical 章</td><td>收敛参照系</td><td>A2A/ACP 的版本化规范</td><td>对比观察卡缺口</td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li><strong>证伪入口</strong>：每张卡的第一手断言都应能在其 canonical URL 找到原文；找不到即降级为传闻并修卡。</li><li>未决 1：发现层（ARD / Registry / ANS / DIR）最终收敛形态——是并存互补还是一个赢家，2026 内难有定论。</li><li>未决 2：支付层（x402 vs MPP vs AP2+UCP vs Agentic Commerce Protocol）的头设计与轨道之争；MPP↔x402 的兼容映射实际互操作性未验证。</li><li>未决 3：WebMCP 的 W3C 轨道走向与跨浏览器支持；NLIP 的实际采用度。</li><li>未决 4：AGNTCY OASF 与 A2A Agent Card、ADL 与两者的转换关系（「生成」还是「取代」）。</li></ul><p><strong>learn-ai 到此为止</strong>：观察卡与门槛判断。<strong>继续去哪</strong>：已收敛协议的深度章 → <a href="./a2a.html">A2A</a> / <a href="./acp-agent-client.html">ACP</a> / <a href="./ag-ui.html">AG-UI</a> / <a href="./a2ui-mcp-apps.html">A2UI 与 MCP Apps</a>；升格请求 → 给本仓提 issue 并附五条门槛的证据。</p>',50)])])}const P=r(n,[["render",i]]);export{m as __pageData,P as default};
